import{_ as l,o as e,c as o,a2 as c}from"./chunks/framework.BKIQXCqS.js";const S=JSON.parse('{"title":"Изменения","description":"","frontmatter":{},"headers":[],"relativePath":"ru/changelog.md","filePath":"ru/changelog.md"}'),a={name:"ru/changelog.md"};function d(t,i,r,s,n,h){return e(),o("div",null,[...i[0]||(i[0]=[c('<h1 id="изменения" tabindex="-1">Изменения <a class="header-anchor" href="#изменения" aria-label="Permalink to &quot;Изменения&quot;">​</a></h1><p>Что менялось в каждой версии расширения, новые сверху.</p><h2 id="_4-1-0-—-2026-10-01" tabindex="-1">4.1.0 — 2026-10-01 <a class="header-anchor" href="#_4-1-0-—-2026-10-01" aria-label="Permalink to &quot;4.1.0 — 2026-10-01&quot;">​</a></h2><h3 id="url-паттерны" tabindex="-1">URL-паттерны <a class="header-anchor" href="#url-паттерны" aria-label="Permalink to &quot;URL-паттерны&quot;">​</a></h3><ul><li>Паттерн в формате браузера (<code>https://site.com/*</code>) больше не расширяется молча на все поддомены: правило срабатывает на <code>site.com</code> и <code>www.site.com</code>, как и показывает попап. То же для <code>http*://site.com</code>. Нужны поддомены — напишите <code>*.</code> явно: <code>https://*.site.com/*</code></li><li>Адрес без пути (<code>https://site.com</code>, <code>https://site.com?x=1</code>) тоже больше не расширяется на поддомены</li><li>Старые паттерны без схемы работают так, как их всегда показывал попап. <code>site.com</code>, <code>*site.com*</code> и <code>*.site.com</code> — это сайт и его поддомены на <code>http</code> и <code>https</code>, <code>www.site.com</code> — <code>www.site.com</code> и <code>site.com</code>. Раньше JS по <code>*site.com*</code> и <code>*.site.com</code> на самом сайте не выполнялся, хотя попап показывал правило. <code>/admin</code> — раздел на любом сайте</li><li>Попап, счётчик на иконке и CSS без разрешения на пользовательские скрипты (Firefox без разрешения, Яндекс без режима разработчика) теперь определяют сайты правила ровно так же, как браузер для JS. Паттерн вида <code>*site.com*</code> больше не срабатывает на чужих адресах, где <code>site.com</code> встречается в query</li><li>Паттерн, который браузер не примет (звёздочка внутри хоста, например <code>https://customer*.site.com/*</code>, или схема, в которую расширение не внедряется, например <code>chrome-extension://</code>), помечается красным в поле URL и в списке правил. Раньше он молча выключал всё правило, теперь пропускается только он, а остальные паттерны правила работают. Попап и счётчик на иконке такое правило на этих адресах не показывают</li><li>Если браузер не примет исключение (<code>!https://login*.site.com/*</code>), правило по-прежнему не выполняется нигде — иначе оно сработало бы на исключённых адресах, — но теперь поле URL и список правил говорят, какое исключение исправить</li><li>Явное исключение <code>!https://www.site.com/*</code> больше не задевает <code>site.com</code>: исключения уходят браузеру как написаны</li><li>Убраны пометка «устаревший формат URL» и жёлтые подсказки конвертации: период перехода на MV3 прошёл, паттерны без схемы расширение переводит само. Убран и строгий режим URL (флаг старых правил и API агента): все паттерны конвертируются одинаково</li><li>Кириллические домены в паттернах (<code>пример.рф</code>, <code>https://пример.рф/*</code>) работают: расширение переводит их в punycode</li><li>Firefox: паттерн с портом (<code>localhost:3000</code>, <code>http://localhost:*/*</code>) работает. Раньше <code>:*</code> выключал всё правило, а номер порта не срабатывал нигде. Firefox не различает порты, поэтому в нём такое правило срабатывает на всех портах хоста, а исключение с портом снимает правило со всех портов. Паттерн вида <code>*://*:8080/*</code> (любой сайт на конкретном порту) в Firefox помечается красным: без порта он означал бы все сайты</li><li>Паттерн с заглавными буквами в схеме или домене (<code>HTTPS://Site.com/*</code>) больше не выключает правило: схема и домен приводятся к нижнему регистру</li></ul><h3 id="библиотеки" tabindex="-1">Библиотеки <a class="header-anchor" href="#библиотеки" aria-label="Permalink to &quot;Библиотеки&quot;">​</a></h3><ul><li>Библиотека, чей файл не скачался, помечена красным значком в списке библиотек, а правила, которые от неё зависят, — в списке правил. Раньше такая библиотека молча выпадала из правила, и на странице появлялось <code>$ is not defined</code> при включённой галочке jQuery</li><li>Сбой «Скачать повторно» показывает ошибку с причиной (например, <code>HTTP 404</code>) вместо сообщения об успехе</li><li>Смена адреса библиотеки в редакторе сразу скачивает файл с нового адреса. Раньше правила продолжали получать код прежнего файла, пока библиотеку не удалишь и не создашь заново</li><li>«Скачать заново» в редакторе библиотеки качает сохранённый адрес. Раньше он качал набранный, но не сохранённый адрес, и после «Отмены» правила получали файл, которого в списке нет</li></ul><h3 id="инструменты-агента" tabindex="-1">Инструменты агента <a class="header-anchor" href="#инструменты-агента" aria-label="Permalink to &quot;Инструменты агента&quot;">​</a></h3><ul><li><code>list_rules</code> с <code>include: [&quot;digest&quot;]</code> отдаёт и флаг <code>important</code>: сверка правил со своей копией обходится одним вызовом, без <code>get_rule</code> на каждое правило</li><li>MCP-сервер при закрытом браузере отвечает на запрос списка инструментов за 4 секунды, а не за 45. Раньше <code>claude mcp list</code> писал <code>tools fetch failed</code>, хотя сервер работал, а сессия агента стартовала на полминуты дольше. Браузер, открытый позже, подхватывается сам: сервер сообщает агенту о новых инструментах</li></ul><h3 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h3><ul><li>Меню параметров правила в редакторе (включение, облако, общее правило, отмена изменений, удаление) и меню «Модули» открываются с клавиатуры: Tab до кнопки, Enter — фокус на первом пункте, Esc — назад. Раньше они открывались только наведением мыши, и удалить правило с клавиатуры было нельзя. Сортировка списка правил и окна подтверждения тоже держат фокус внутри и закрываются по Esc</li><li>Наведение на меню «Модули» или параметры правила больше не уводит фокус из поля, в котором вы печатаете</li><li>Клик мимо окна подтверждения удаления закрывает его как отказ</li><li>Удалённое правило больше не может остаться работать на сайтах. Раньше, если правило удаляли в момент, когда фон перерегистрировал скрипты, его скрипт в редком случае возвращался и внедрялся до следующей полной перерегистрации</li><li>Новый адрес правила или набор библиотек, сохранённые в редакторе или агентом, применяются сразу. Раньше при медленной записи правило изредка регистрировалось со старым адресом и работало так до следующего сохранения</li></ul><h2 id="_4-0-0-—-2026-09-26" tabindex="-1">4.0.0 — 2026-09-26 <a class="header-anchor" href="#_4-0-0-—-2026-09-26" aria-label="Permalink to &quot;4.0.0 — 2026-09-26&quot;">​</a></h2><h3 id="редактор" tabindex="-1">Редактор <a class="header-anchor" href="#редактор" aria-label="Permalink to &quot;Редактор&quot;">​</a></h3><ul><li>Переход с ACE Editor на CodeMirror 6: улучшенная производительность, поддержка мобильных устройств, современная архитектура расширений</li><li>Enter в редакторе снова просто переводит строку. Раньше подсказку автодополнения принимал Enter, и при наборе кода вместо новой строки вставлялось случайное имя свойства или переменной. Теперь подсказка принимается по Tab</li><li>Поиск и замена (Ctrl+F) переехали в собственную панель над кодом: поле поиска со счётчиком совпадений («1 из 6»), переходы по Enter и Shift+Enter, режимы «учитывать регистр», «регулярное выражение», «слово целиком», замена одного совпадения и всех сразу. Панель на языке интерфейса, в теме редактора</li><li>Панель поиска больше не перекрывает нижние элементы редактора — переключатели режима запуска и красную панель ошибок компиляции. Это касается и диалога перехода к строке (Ctrl+Alt+G)</li><li>Найденные совпадения подсвечиваются акцентным цветом расширения вместо кислотно-циановой подсветки по умолчанию; текущее совпадение выделено ярче остальных</li><li>Подсказки автодополнения оформлены как остальные всплывающие панели: скруглённые углы, фон и шрифт редактора</li></ul><h3 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h3><ul><li>Удалена опция «Программное подключение CSS» (isoCSS) — CSS теперь всегда внедряется через DOM (<code>&lt;style&gt;</code>), что обеспечивает стабильную отрисовку и предсказуемый каскад</li><li>CSS Live: обновление стилей на открытых вкладках без перезагрузки — после сохранения CSS изменения применяются мгновенно</li></ul><h3 id="firefox" tabindex="-1">Firefox <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Firefox&quot;">​</a></h3><ul><li>Поддержка Firefox MV3 (Firefox 136+)</li><li>В Firefox снова компилируются SCSS и SASS. Раньше политика безопасности страницы расширения блокировала компилятор, и стили не собирались</li><li>В Firefox загрузка JSON, сброс и «Скачать из облака» больше не заканчиваются красным тостом ошибки при правилах, где есть и JS, и CSS. Данные при этом записывались, но скрипты не перерегистрировались, и на страницах работали старые версии правил</li></ul><h3 id="список-правил" tabindex="-1">Список правил <a class="header-anchor" href="#список-правил" aria-label="Permalink to &quot;Список правил&quot;">​</a></h3><ul><li>Строка правила перестроена: название и адрес слева, переключатель и значки состояний — справа, каждый на своём уровне. Список читается по колонкам, а не сплошной массой</li><li>Вместо URL-паттерна целиком под названием теперь стоят только сайты — <code>youtube.com</code>, <code>jira.company.com</code>. Схема, путь и звёздочки одинаковы почти у всех правил и мешали читать список; полный паттерн показывается по наведению</li><li>Переключатель включённого правила больше не мозолит глаза: он появляется при наведении на строку. Выключенное правило видно всегда — переключатель на месте, а сама строка приглушена</li><li>Состояния («черновик», «общее правило», «устаревший формат URL») стали аккуратными значками с подсказкой вместо цветных точек, значение которых приходилось угадывать</li><li>Красным помечается только правило с ошибкой компиляции: единственное состояние, требующее вмешательства</li><li>Правило со сломанным SCSS получает отметку ошибки и после загрузки JSON или восстановления из облака — когда стиль в файле ещё не собран (бэкап старой версии, JSON без css) или отметка в нём разошлась с ошибкой. Раньше отметки не было, и правило со сломанным стилем выглядело рабочим</li><li>Переключатель стал полноценной кнопкой: по нему можно попасть мышью, дойти табом и нажать с клавиатуры; на сенсорных экранах он виден всегда</li><li>По всей странице настроек вернулась видимая рамка фокуса — без неё работа с клавиатуры была вслепую. У полей ввода по клику мышью остаётся одна жёлтая рамка, без второго кольца поверх неё</li></ul><h3 id="url-паттерны-1" tabindex="-1">URL-паттерны <a class="header-anchor" href="#url-паттерны-1" aria-label="Permalink to &quot;URL-паттерны&quot;">​</a></h3><ul><li>Новый редактор URL-паттернов: textarea с построчным вводом и inline-валидацией вместо popup с документацией</li><li>Цветные индикаторы для каждого URL: зелёный — валидный V3-паттерн, жёлтый — будет сконвертирован</li><li>Убрана опция «Не конвертировать» из UI (конвертация всегда включена)</li></ul><h3 id="интерфеис" tabindex="-1">Интерфейс <a class="header-anchor" href="#интерфеис" aria-label="Permalink to &quot;Интерфейс&quot;">​</a></h3><ul><li>Шрифт интерфейса стал компактнее: 13px в основном тексте и 11px в подписях вместо 14 и 12. На экран помещается больше правил и настроек, а плотность списка и отступы не изменились</li><li>Размер шрифта в редакторах кода не затронут: он остаётся тем, что выставлен в настройках редактора</li><li>Сообщение об ошибке говорит, что не удалось и почему: «Не удалось импортировать JSON» и текст причины вместо одного слова «Ошибка» — при импорте, сбросе, работе с облаком, скачивании библиотеки, форматировании кода, копировании и загрузке данных на старте. Такая ошибка остаётся на экране, пока её не закроешь, и её текст можно выделить и скопировать. Одна и та же ошибка не размножается, а на экране их не больше трёх</li><li>«Хранилище только для чтения» и «не удалось сохранить изменения» держатся 7 секунд вместо 3 и помечены значком предупреждения, а не галочкой успеха</li><li>Уведомления снова появляются внизу по центру и по ширине текста, а не в левом верхнем углу во всю ширину окна</li><li>В настройках инструментов для агентов больше нет служебной приписки «(no_api)» после «недоступно»</li><li>Поля в настройках перестроены: подпись стоит над полем, а само поле и выпадающий список занимают всю ширину панели. Длинное значение — название шрифта, тема редактора — больше не обрезается на середине</li><li>Галочка теперь стоит перед своей подписью, а не в конце строки: видно, что включено, одним взглядом сверху вниз</li><li>До чекбоксов в панели настроек теперь можно дойти табом и переключить пробелом. Раньше Tab их пропускал</li><li>Размер шрифта и размер отступов редактора стоят в одной строке — две настройки перестали занимать два экранных ряда</li><li>Текстовые поля держатся лёгким фоном вместо постоянной рамки; рамка проявляется по наведению. Панель настроек перестала выглядеть решёткой из рамок</li><li>Углы полей ввода и выпадающих списков скруглены слабее — 4px вместо 8px, как у кнопок</li><li>Галочки стали мельче (18px вместо 24px), а у выключенной рамка теперь серая, не жёлтая: жёлтый контур у каждой снятой галочки читался как «требует внимания»</li><li>Панель настроек разделена: MCP и подключение агентов вынесены на отдельную вкладку, резервные копии и синхронизация — на вкладку «Хранилище». В настройках расширения остались язык, счётчик и редактор</li><li>Заголовки групп в левой панели лишились серой полосы: группы разделяет тонкая линия, а треугольник складывания стоит у правого края</li><li>В попапе правила отсортированы по точности попадания: сначала написанные для раздела этого сайта, затем для сайта целиком, в конце — работающие везде. Раньше порядок был случайным (по дате создания), и правило, написанное специально для открытой страницы, уезжало в хвост за спины универсальных и попадало под скролл — казалось, что его нет</li><li>В строке правила сайт, из-за которого правило сюда попало, стоит первым и не приглушён. У правила на десяток доменов сработавший домен больше не прячется в хвосте «+N»</li><li>Попап стал выше (600px вместо 400): список правил реже упирается в скролл</li></ul><h3 id="интеграция-с-ии-агентами" tabindex="-1">Интеграция с ИИ-агентами <a class="header-anchor" href="#интеграция-с-ии-агентами" aria-label="Permalink to &quot;Интеграция с ИИ-агентами&quot;">​</a></h3><ul><li>Новая настройка «Разрешить MCP-подключения» (по умолчанию выключена): внешние MCP-клиенты — Claude Code, Cursor и другие — через локальный сервер, а пока открыта страница настроек и агент в браузере, могут просматривать правила, создавать, править, включать и удалять их</li><li>Агент видит, какие правила применяются к конкретному адресу и какие подходят, но выключены — обычный ответ на вопрос «почему правило не работает»</li><li>Правило, открытое в редакторе с несохранёнными правками, агенту недоступно на запись: сначала нужно сохранить или закрыть его</li><li>Разрешение не переносится бэкапом: восстановление данных на другом устройстве не включает доступ агента автоматически</li><li>Внешние агенты (Claude Code, Cursor) подключаются через локальный MCP-сервер: команда для подключения показывается прямо в настройках, открытая страница расширения при этом не нужна</li><li>Сервер устанавливается одной командой из npm (<code>npx -y user-js-css-mcp</code>) — путь к файлам расширения больше не нужен. Тем, у кого стоит bun, подходит и <code>bunx user-js-css-mcp</code>: раньше под bun мост молча зависал</li><li>Агент может завести, переименовать и удалить библиотеку; удаление библиотеки, от которой зависят правила, отклоняется с перечислением этих правил</li><li>Агент видит, какие правила зависят от правки: при изменении общего правила в ответе перечисляются те, чьё поведение тоже изменится</li><li>Новый отчёт «чем я не пользуюсь»: сколько раз каждое правило подошло к открытой странице, какие библиотеки не нужны ни одному правилу. Считаются только совпадения — адреса страниц не сохраняются, счёт идёт лишь при включённой настройке «Разрешить MCP-подключения»</li><li>В диагностике видны библиотеки, которые не скачались: частая причина «правило сохранено и не работает»</li><li>Вкладка MCP показывает состояние подключения цветной точкой: не подключено, подключено (с названиями клиентов), требуется переподключение или обновление сервера — у каждого одно действие, а под заголовком — что проверить или почему отказ. Раньше отказ был виден только в консоли</li><li>Всё на вкладке MCP видно сразу, без свёрток, по порядку установки: клиент, способ запуска, команда и её копирование, секрет. Пока подключения не разрешены, поля видны, но неактивны</li><li>Установка сервера под свой клиент: готовая команда для Claude Code, Codex и Gemini CLI, JSON для Claude Desktop и прочих, установка в один клик для Cursor и VS Code; запуск через npx или bunx. Команда видна сразу — секрет в ней скрыт, но копируется настоящий. Для Claude Code и Gemini CLI есть галка «Установить только в папку проекта»</li><li>Секрет моста скрыт на экране (страницу настроек показывают на скриншотах); рядом кнопки показать, скопировать и заменить, если он утёк</li><li>Агент может выгрузить полный бэкап прямо в файл и заново зарегистрировать все скрипты, если браузер отказал в регистрации</li><li>Агент может восстановить данные из файла бэкапа: целиком либо слиянием по id — правила из файла ложатся поверх текущих, остальные остаются на месте</li><li>Несколько сессий агента работают одновременно: вторая и последующие подключаются к той, что заняла порт, вместо того чтобы остаться без инструментов</li><li>Поиск по коду правил: агент находит, в каком правиле определена функция или вызов, не вычитывая правила подряд</li><li>Пакетная правка правил одним вызовом: набор проверяется целиком до первой записи</li><li>Правка правила может быть защищена отпечатком: если человек изменил правило в браузере, пока агент готовил правку, запись отклоняется вместо молчаливой перезаписи</li></ul><h3 id="исправления" tabindex="-1">Исправления <a class="header-anchor" href="#исправления" aria-label="Permalink to &quot;Исправления&quot;">​</a></h3><ul><li>Переключатель правила на странице настроек снова выключает правило сразу. Раньше он менял только отметку в списке, а скрипт продолжал внедряться на сайт, пока правило не открыли в редакторе</li><li>Загрузка JSON и восстановление из облака пересобирают стили из SCSS заново, а не берут готовый CSS из файла. Раньше стиль, собранный в файле с ошибкой или по старой версии исходника, приезжал как есть и чинился только правкой правила</li><li>Правило, у которого стёрли весь код или адрес, перестаёт работать на сайте. Раньше продолжала действовать его прежняя версия</li><li>Счётчик на иконке расширения больше не учитывает выключенные правила</li><li>Правило, подключённое модулем к другому правилу, и библиотека, общая для нескольких правил, выполняются на странице один раз. Раньше такой код запускался повторно: второе правило падало с «Identifier has already been declared», а библиотека перезагружалась и теряла подключённые к ней плагины</li><li>Синтаксическая ошибка в модуле больше не останавливает код правила, которое его подключило, а номера строк в ошибках правила совпадают с редактором и не сдвигаются длиной модулей</li><li>После обновления расширения в консоли уже открытых вкладок больше не появляется «Extension context invalidated» при каждом переходе внутри сайта</li><li>Облачный бэкап занимает на ~7% меньше квоты синхронизации: данные кодируются плотнее (Z85 вместо base64). Бэкапы в старом формате восстанавливаются как раньше. Бэкап, выгруженный этой версией, не прочитает устройство со старой версией расширения — его нужно обновить</li><li>URL-паттерны со схемой (<code>https://site.com/*</code>) теперь привязаны к началу адреса — правило больше не срабатывает ложно, если домен встретился в query-строке другого сайта</li><li>Защита от потери данных: при сбое миграции хранилища данные на диске больше не затираются пустым состоянием</li><li>Корректная обработка ошибок при восстановлении из облака — повреждённые данные не вызывают неинформативный сбой</li><li>Внешние модули-библиотеки загружаются только по http(s) (блокировка <code>file:</code>/<code>data:</code>/<code>javascript:</code>)</li><li>Длительность дебаунса сохранения снова учитывается в popup (50 мс)</li><li>Защита от двойного сохранения правила и гонки с автосохранением черновика</li><li>Устранено дублирование CSS на SPA-сайтах после выгрузки Service Worker: трекинг применённых стилей сохраняется в session storage и восстанавливается при перезапуске SW</li><li>Ошибки синхронизации с облаком (повреждённые/несовместимые данные) теперь показываются уведомлением, а не приводят к молчаливому сбою с закрытием диалога «как будто успешно»</li><li>Popup: предупреждение «нет доступа» больше не мигает на обычных страницах при открытии и не показывается на системных (chrome://, файлы, новая вкладка) — только когда инъекция действительно недоступна</li><li>Устранена запись черновика в чужое правило: при быстром переключении между правилами (в окне автосохранения 500 мс) код правила A мог перезаписать правило B</li><li>Замена данных хранилища стала атомарной: при сбое записи (квота облака, ошибка браузера) старые данные больше не стираются — восстановление из облака и миграция не могут оставить хранилище пустым</li><li>Перед загрузкой в облако размер данных проверяется на актуальность, а не по значению на момент открытия страницы</li><li>Несохранённые правки правила (имя, флаги) больше не откатываются при одновременной работе в popup и на странице настроек</li><li>Chrome: правила теперь применяются при SPA-навигации через <code>history.replaceState</code> (раньше — только <code>pushState</code> и переходы по истории)</li><li>Chrome: включение Developer mode теперь подхватывается автоматически в течение 30 секунд — раньше детект не переживал выгрузку Service Worker и требовал пересохранения правила</li><li>SCSS-правила без скомпилированного CSS (например, после миграции со старых версий) теперь докомпилируются при открытии страницы настроек — раньше стиль молча не применялся до пересохранения правила</li><li>Закрыта дыра в матчинге URL: паттерны <code>*://site.com/*</code>, <code>http*://site.com/*</code> и <code>*://*.site.com/*</code> больше не срабатывают, когда целевой адрес встроен в query-строку чужого URL (wildcard схемы/хоста не пересекает <code>://</code> и <code>/</code>)</li><li>Если миграция данных со старой версии не удалась, расширение переходит в режим «только чтение» вместо записи новой версии поверх старых данных — миграция повторится после исправления, данные не теряются</li><li>Сбой восстановления из облака или импорта больше не оставляет все скрипты отключёнными: перерегистрация происходит только после успешной замены данных</li><li>Повторное нажатие «Сохранить» во время долгого сохранения (SCSS-компиляция) больше не игнорируется — сохранения выполняются последовательно</li><li>Загрузка в облако при остатках старого legacy-бэкапа больше не блокируется навсегда по квоте: при нехватке места старые данные освобождаются и запись повторяется</li><li>Режим «только чтение» при сбое миграции теперь распознаёт все старые форматы данных (v1–v10), показывает пользователю уведомление и не мешает восстановлению: сброс хранилища, импорт бэкапа и восстановление из облака работают и снимают блокировку</li><li>Восстановление из облака больше не подхватывает случайно уцелевший древний бэкап старого формата, если рядом лежит новый</li><li>Паттерны со схемами вида <code>chrome-extension://</code> тоже якорятся к началу адреса</li><li>Устранены гонки при одновременной работе: создание/удаление правила больше не теряется при записи из попапа, отложенное сохранение не коммитит черновик другого правила после переключения, фоновая докомпиляция SCSS не затирает свежесохранённые правки</li><li>Паттерн без пути (<code>https://example.com</code>) больше не срабатывает на похожих доменах (<code>example.com.evil.com</code>)</li><li>Сохранение правила, поставленное в очередь перед переключением на другое правило, теперь доводится до конца, а двойное нажатие «Сохранить» на новом правиле не создаёт пустой дубль</li><li>Восстановление/импорт/сброс применяются целиком — несохранённые локальные правки больше не «переживают» явное восстановление</li><li>Учтён формат ошибки квоты Firefox при загрузке в облако</li><li>Если чанковый облачный бэкап оказался повреждён (оборвавшаяся запись), восстановление использует уцелевший старый бэкап вместо ошибки</li><li>Сбой сохранения нового правила больше не «ломает» кнопку сохранения навсегда: черновик остаётся черновиком, показывается уведомление об ошибке, повторное сохранение работает</li><li>После восстановления из облака открытый редактор перечитывает контент правила — раньше он мог записать старый код поверх только что восстановленных данных</li><li>Удалённое правило больше не «воскресает» пустым, если в момент удаления попап или второе окно записали изменения</li><li>Тоггл правила из попапа больше не откатывается молча, когда это же правило открыто и правится на странице настроек (слияние по полям вместо «целиком»)</li><li>Несохранённые правки библиотек и настроек больше не затираются записью из другого окна (та же защита, что была у правил)</li><li>Если миграция данных не удалась, страница настроек больше не ломается на legacy-данных: показываются дефолты в режиме «только чтение», данные на диске не тронуты</li><li>Провал загрузки хранилища в фоне больше не приводит к снятию рабочих скриптов: перерегистрация пропускается до успешного старта</li><li>Восстановление из облака и сброс хранилища у пользователей без Developer mode больше не показывают ложную ошибку при успешной операции; удаление правила без dev mode больше не оставляет «зомби» в списке</li><li>Незакомпилированный SCSS больше не теряется, если компиляция при открытии настроек не удалась (сбой sandbox/записи) — повтор произойдёт при следующем открытии, а не при случайном перезапуске SW; добор запускается и если настройки открыты раньше, чем фон успел выставить маркер</li><li>Импорт бэкапа и восстановление из облака больше не выключают «Разрешить MCP-подключения»: настройка описывает браузер, а не данные, и в бэкап не попадает — раньше её приходилось включать заново руками</li><li>Временный сбой обновления стилей вкладки больше не стирает трекинг применённого CSS — устаревший стиль корректно снимается после восстановления</li><li>Индикатор «сохранено» в редакторе больше не загорается при сбое записи — правило остаётся помеченным как черновик до успешного сохранения</li><li>Новое правило больше не открывается с чужим JS/CSS: черновик больше не читается с диска, а мусорный ключ черновика, записанный старыми версиями, удаляется при старте</li><li>Ctrl+S теперь сохраняет правило на любой раскладке, включая русскую и альтернативные латинские (Dvorak, Colemak)</li><li>Починено скругление углов попапа расширения (подсказки в попапе при этом больше не обрезаются)</li><li>Восстановление из облака, импорт и сброс теперь доходят до всех открытых окон: раньше вторая вкладка настроек или попап могли вернуть на диск своё старое состояние, а открытый редактор — записать поверх восстановленного правила старый код</li><li>Удаление правила больше не сбивает сохранение изменений, идущее в этот момент из другого окна</li><li>Настройки больше не падают на данных старого формата, если миграция не удалась: список правил и регистрация скриптов работают с валидными значениями</li><li>Импорт бэкапа применяется одной операцией — двойное применение сбивало восстановление открытого в редакторе правила</li><li>SCSS, который компилируется в пустой CSS (например, из одних комментариев), больше не заставляет настройки при каждом открытии заново гонять компиляцию</li><li>Открытие страницы настроек стало легче: докомпиляция стилей читает только нужные правила, а не всё хранилище целиком</li><li>Сообщение о режиме «только чтение» больше не появляется, если расширение просто ещё дообновляет данные, и не советует сброс хранилища — он уничтожил бы данные, которые нужно восстановить</li><li>Загрузка в облако перестала архивировать данные дважды за клик; при нехватке места показывается уведомление, а не молчаливое бездействие кнопки</li><li>Сбой сохранения правил, библиотек или настроек теперь всегда виден: раньше при ошибке записи изменение оставалось на экране, но пропадало после перезагрузки страницы</li><li>Если облачный бэкап повреждён и восстановление идёт из старой резервной копии, об этом сообщается — раньше показывалось обычное «готово»</li><li>Правило с SCSS, который компилируется в пустой CSS, больше не заставляет расширение перекомпилировать его каждые полминуты</li><li>Сбой очистки устаревших ключей при импорте или сбросе больше не выглядит как провал миграции и не оставляет расширение в режиме «только чтение» с уже корректными данными</li><li>Изменение правила из попапа больше не теряется, если оно было создано в настройках в тот же момент</li><li>Если миграция данных не удалась, переключение Developer mode больше не снимает все зарегистрированные скрипты</li><li>Страница настроек, открытая во время обновления данных, больше не может остаться в режиме «только чтение» до перезагрузки</li><li>Сбой автосохранения кода в редакторе теперь виден: раньше набранный текст молча не сохранялся</li><li>Докомпиляция стилей при открытой странице правила больше не откатывается автосохранением редактора</li><li>Ctrl+S на раскладках Dvorak и Colemak больше не перехватывает Ctrl+O</li><li>Загрузка в облако собирает бэкап после подтверждения — правки, сделанные во время диалога, тоже попадают в копию</li><li>Правило с адресом без пути, но с параметрами (<code>https://example.com?utm=1</code>), снова срабатывает на адресах с более длинной query-строкой</li><li>Переименование правила в одном окне больше не теряется, если в другом в этот момент шло автосохранение кода</li><li>Страница настроек больше не может залипнуть в режиме «только чтение» из-за совпадения по времени с обновлением данных в фоне</li><li>Счётчик на иконке расширения снимается, если данные не загрузились, — раньше мог висеть устаревшим</li><li>Ctrl+Shift+S больше не перехватывается редактором</li><li>Уведомления теперь показываются и в попапе: сбой сохранения при переключении правила больше не остаётся незамеченным</li><li>Сбой загрузки CDN-модулей больше не останавливает применение стилей во всех вкладках</li><li>Паттерн с подстановкой в домене (<code>https://*.example.com</code>) больше не срабатывает, когда целевой адрес спрятан в параметрах чужой ссылки</li><li>Перетаскивание библиотек больше не откатывается, если в этот момент пришло изменение из другого окна</li><li><strong>Исправлена потеря правил при обновлении с версий 2–8</strong>: данные старого формата стирались до того, как миграция успевала их прочитать</li><li>Кнопка «Загрузить в облако» заблокирована, пока данные не мигрированы: раньше ею можно было затереть рабочий бэкап неисправными данными</li><li>Восстановление из уцелевшей старой копии срабатывает и когда облачный бэкап повреждён в середине</li><li>Трекинг применённых стилей больше не упирается в лимит служебного хранилища при широких правилах и множестве вкладок</li><li>Включение Developer mode подхватывается и в браузерах без session storage</li><li>Стили SCSS, докомпилированные при открытии настроек, теперь сразу применяются на страницах — раньше требовалось пересохранить правило вручную</li><li>После восстановления данных из облака (или сброса) расширение снова начинает применять стили без перезапуска браузера</li><li>Время изменения правила больше не теряется, если во время сохранения пришло изменение из другого окна</li><li>Правки, сделанные в настройках, больше не теряются при одновременном изменении из попапа: результат слияния теперь дописывается на диск, а не остаётся только на экране</li><li>Ошибка сохранения показывается один раз, а не потоком уведомлений при каждой правке</li><li>Удалённое в другом окне правило больше не всплывает обратно, если его контент читался в этот момент</li><li>Переключение «!important» больше не откатывается следующим нажатием клавиши: пересобранный стиль остаётся в редакторе и на диске</li><li>Сбой компиляции стиля при автосохранении больше не отменяет сохранение набранного кода</li><li>Если правило удалили в другом окне, редактор сообщает об этом, а не делает вид, что сохранил изменения</li><li>Откат расширения на более старую версию больше не перезаписывает данные нового формата: они остаются нетронутыми в режиме «только чтение»</li><li>Остатки данных очень старых версий убираются с диска и больше не занимают место в облачной копии</li><li>Восстановление из облака больше не сбрасывает пометки «черновик» и «ошибка» у открытого правила</li><li>Ошибка при загрузке файла бэкапа или сбросе хранилища теперь показывается, а не проходит незаметно</li><li>Импорт неполного файла бэкапа больше не ломает работу расширения до перезагрузки страницы</li><li>Сохранение правила, начатое до восстановления из облака, больше не записывается поверх восстановленных данных</li><li>Если компиляция стиля не удалась при сохранении, правило больше не остаётся с CSS от предыдущей версии кода: пересборка выполнится при следующем открытии настроек</li><li>Только что созданное правило больше не исчезает из списка, если в этот момент пришла запись из другого окна</li><li>Настройки редактора, изменённые одновременно в двух окнах, больше не откатывают друг друга</li><li>Загрузка не того файла в «Загрузить JSON» больше не стирает все правила: пустой или неподходящий файл отклоняется с ошибкой</li><li>Импорт файла без части данных больше не оставляет в списке правила, которых уже нет</li><li>Страница настроек больше не остаётся пустой, если данные не удалось загрузить — показываются дефолты и уведомление об ошибке</li><li>Восстановление из облака во второй вкладке больше не стирает библиотеки и настройки, которых оно не касалось</li><li>Повреждённый файл бэкапа отклоняется до записи, а не после того, как данные уже заменены</li><li>Уведомления, возникшие в момент открытия страницы, больше не теряются</li><li>Страница настроек открывается и после импорта файла без блока настроек — берутся значения по умолчанию</li><li>Импорт файла без библиотек больше не отменяется вторым открытым окном</li><li>Правило, сохранённое после переключения на другое, больше не остаётся помеченным как черновик</li><li>Переключение между правилами больше не переносит пометку «черновик» на предыдущее правило</li><li>Файл бэкапа с повреждёнными записями правил отклоняется целиком, а не после записи на диск</li><li>Импорт бэкапов, сделанных старыми версиями расширения, снова работает</li><li>Восстановление из облачной копии старого формата снова работает</li><li>Настройки, изменённые в другом окне, больше не откатываются, если на диске их ещё не было</li><li>AltGr+S (польская и похожие раскладки) снова печатает букву, а не сохраняет правило</li><li>В режиме «только чтение» удаление правила больше не стирает данные, которые расширение защищает от перезаписи</li><li>Только что добавленная библиотека больше не исчезает при одновременной записи из другого окна</li><li>Ошибка удаления правила теперь видна, а не проходит незаметно при закрытии диалога</li><li>Сбой восстановления из облака показывает настоящую причину, а не сообщение о режиме «только чтение»</li><li>Если данные не удалось загрузить, изменения больше не сохраняются вообще: раньше первая же правка могла стереть список правил (сами правила при этом оставались на диске). Показывается уведомление с просьбой перезагрузить страницу</li><li>После успешного восстановления из облака сохранение снова работает без перезагрузки страницы</li><li>Импорт очень старых бэкапов (версии 2–8) снова работает</li><li>Ошибка удаления библиотеки теперь видна; удаление библиотеки, отсутствующей в списке, больше не удаляет другую</li><li>Галочка «лигатуры» в настройках редактора снова соответствует тому, как выглядит код</li><li>Если библиотеку не удалось удалить, она остаётся в списке — и попытку можно повторить</li><li>Переключение «!important» при недоступной компиляции больше не оставляет правило с прежним стилем навсегда — пересборка выполнится при следующем открытии настроек</li><li>Разрешение на инструменты для ИИ-агентов больше не сбрасывается при перезагрузке страницы настроек</li><li>Секрет моста к MCP-серверу переживает импорт, сброс и восстановление из облака — подключённый агент не теряет доступ молча</li><li>Секрет моста больше не меняется при открытии страницы настроек — подключённый MCP-сервер не теряет доступ</li><li>Команда подключения MCP-сервера на странице настроек запускает его под node: под bun мост молча не поднимался</li><li>ИИ-агент видит и меняет настройки расширения и поведение правил (запуск до загрузки страницы, изолированный мир, вложенные фреймы, строгий URL, исключение из облака)</li><li>Инструменты для ИИ-агентов больше не роняют ошибку в консоль на сайтах, которые используют document.domain</li><li>ИИ-агент видит, почему правило не работает: браузер отказал в регистрации скрипта или не собрался стиль</li><li>Скрипты правил названы в DevTools по имени правила — в консоли сразу видно, какое из них выдало ошибку, вместо <code>&lt;anonymous&gt;</code></li></ul><h3 id="исправления-интеграции-с-агентами" tabindex="-1">Исправления интеграции с агентами <a class="header-anchor" href="#исправления-интеграции-с-агентами" aria-label="Permalink to &quot;Исправления интеграции с агентами&quot;">​</a></h3><ul><li><p>Импорт через агента с заменой (<code>import_storage</code>) отмечает правила, чей SCSS не собрался: <code>get_diagnostics</code> находит их по этой отметке, а раньше пропускал</p></li><li><p><code>get_diagnostics</code> больше не сообщает об отказе регистрации скрипта, который на самом деле стоит. Раньше импорт или перерегистрация от агента, совпавшие с сохранением правила или со страницей настроек, давали ложный отказ «duplicate id»</p></li><li><p>Библиотека, скачанная фоном (первый запуск, восстановление из облака, импорт), сразу попадает в правила: раньше правило продолжало работать без её кода до ручного «Обновить» в карточке библиотеки</p></li><li><p>ИИ-агент видит библиотеку, которая числится в списке, но ни разу не скачалась: <code>get_diagnostics</code> называет её причиной, <code>list_libraries</code> показывает размер кэша</p></li><li><p>Стиль, исправленный ИИ-агентом, пересобирается: раньше правка SCSS или флага important через агента сохранялась, а на страницах оставался стиль от прежнего кода</p></li><li><p>Стиль правила, записанного внешним агентом через MCP, собирается сразу, а не при следующем открытии страницы настроек. То же с импортом через агента и со стилем, чья сборка однажды сорвалась: расширение добирает его само при следующем запуске. Ошибка в таком стиле видна значком в списке правил и в диагностике агента</p></li><li><p>Отказ регистрации инструментов у агента в браузере пишется в консоль один раз и текстом, а не двадцать раз; настройки не называют WebMCP работающим, пока он отклонён</p></li></ul>',30)])])}const m=l(a,[["render",d]]);export{S as __pageData,m as default};
